/// <summary>
/// Task service class
/// </summary>
class METCustomerMDFConsolidationBatchTaskService extends METSysOperationTaskService
{
    guid topPickingProcessId;
    METCustomerMDFConsolidationBatchJobQueue consolidationBatchJobQueue;


}

Method.Source:
/// <summary>
///  Initializes the object.
/// </summary>
protected void initialise()
{
    METCustomerMDFConsolidationBatchContract contract;

    super();

    // get the topPickingProcessId from the contract
    contract            = dataContract as METCustomerMDFConsolidationBatchContract;
    topPickingProcessId = contract.parmTopPickingProcessId();        
}

/// <summary>
/// Execution starts from here 
/// </summary>
/// <param name = "_readPast">boolean</param>
protected void processTask(boolean _readPast)
{
    while (this.getDataFromTopPickingQueue(topPickingProcessId, _readPast))
    {
        try
        {
            if (consolidationBatchJobQueue.RecId != 0)
            {
                ttsbegin;
                this.execute();
                ttscommit;
            }
        }
        catch (Exception::Error)
        {
            // Catch any exception so that any one error won't bring down
            // the entire process of sales order substitution.
            Global::exceptionTextFallThrough();
        }
    }

}

/// <summary>
/// Process method
/// </summary>
/// <param name = "_contract">METCustomerMDFConsolidationBatchContract</param>
public void process(METCustomerMDFConsolidationBatchContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Read data from Queue table
/// </summary>
/// <param name = "_processId">GUID</param>
/// <param name = "_readPast">boolean</param>
/// <returns>boolean</returns>
private boolean getDataFromTopPickingQueue(guid _processId, boolean _readPast)
{
    #OCCRetryCount

    METCustomerMDFConsolidationBatchJobQueue topPickingQueue;
    int backOffWait;

    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    topPickingQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock topPickingQueue
            where topPickingQueue.ProcessId == _processId;

        if (topPickingQueue.RecId)
        {
            //Copies data in METCustomerMDFConsolidationBatchJobQueue from topPickingQueue buffer.
            consolidationBatchJobQueue.data(topPickingQueue);

            topPickingQueue.delete();
        }
        else
        {
            ///Empties the table buffer of METCustomerMDFConsolidationBatchJobQueue.
            DictTable consolidationBatchJobQueueDictTable = new DictTable(tableNum(METCustomerMDFConsolidationBatchJobQueue));
            consolidationBatchJobQueue = consolidationBatchJobQueueDictTable.makeRecord();
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return (consolidationBatchJobQueue.RecId != 0);
}

/// <summary>
/// Execute method - This method populate slot area
/// </summary>
private void execute()
{
    this.executeConsolidation();
    this.executePosting();
}

/// <summary>
/// Execute consolidation
/// </summary>
private void executeConsolidation()
{
    METCustomerMDFCalculationTrans customerMDFCalculationTrans;
    MetCustomerMdfSetupTable customerMDFSetupTable;
    MetCustomerMdfTable customerMDFTable;

    // Consolidation for Daily Consolidation and Free Text Invoice Application Method
    while select ShipDate, SiteId, Warehouse from customerMDFCalculationTrans
        group by ShipDate, SiteId, Warehouse
        exists join customerMDFSetupTable
        exists join customerMDFTable
        where customerMDFCalculationTrans.CustAccount == consolidationBatchJobQueue.CustAccount
           && customerMDFCalculationTrans.CustomerMDFConsolidationTable == 0
           && customerMDFCalculationTrans.CustomerMDFSetupTable == customerMDFSetupTable.RecId
           && customerMDFSetupTable.RefRecId == customerMDFTable.RecId
           && customerMDFTable.ConsolidationMethodEDT == METConsolidationMethodEDT::Daily
           && customerMDFTable.ApplicationMethodEDT == METApplicationMethodEDT::FreeTextInvoice
    {
        METCustomerMDFConsolidation_Daily customerMDFConsolidation = new METCustomerMDFConsolidation_Daily();
        customerMDFConsolidation.parmCustAccount(consolidationBatchJobQueue.CustAccount);
        customerMDFConsolidation.parmShipDate(customerMDFCalculationTrans.ShipDate);
        customerMDFConsolidation.parmSiteId(customerMDFCalculationTrans.SiteId);
        customerMDFConsolidation.parmWarehouse(customerMDFCalculationTrans.Warehouse);
        customerMDFConsolidation.process();
    }
}

/// <summary>
/// Execute posting
/// </summary>
private void executePosting()
{
    METCustomerMDFConsolidationTable consolidationTableGroup;

    // Posting for Daily Consolidation and Free Text Invoice Application Method
    while select ShipDate from consolidationTableGroup
        group by ShipDate
        where consolidationTableGroup.CustAccount == consolidationBatchJobQueue.CustAccount
           && consolidationTableGroup.ConsolidationMethod == METConsolidationMethodEDT::Daily
           && consolidationTableGroup.ApplicationMethod == METApplicationMethodEDT::FreeTextInvoice
           && consolidationTableGroup.PostingRefTableId == 0
           && consolidationTableGroup.PostingRefRecId == 0
    {
        METCustomerMDFPosting_FreeTextInvoiceDaily customerMDFPosting = new METCustomerMDFPosting_FreeTextInvoiceDaily();
        customerMDFPosting.parmCustAccount(consolidationBatchJobQueue.CustAccount);
        customerMDFPosting.parmShipDate(consolidationTableGroup.ShipDate);
        customerMDFPosting.process();
    }       
}
